-- The Ti-TURBO code key (Code keys -> Milling -> Ti-TURBO), from the ISCAR
-- e-catalog's Ti-TURBO families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.titurbo', $ck${"title": "Ti-TURBO code key – solid carbide endmills for titanium", "subtitle": "Solid carbide endmills with different helix, chamfered edges and variable pitch for chatter damping on titanium", "example": "ECK-H4M 10-20C10CFR0.5-72", "decoder": "ti-turbo", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "ECK", "rows": [{"code": "ECK", "meaning": "Endmill for titanium, with different helix and variable pitch"}]}, {"key": "t-helix", "title": "Helix", "rows": [{"code": "H", "meaning": "Different helix and variable pitch (CHATTER-FREE)"}]}, {"key": "t-flutes", "title": "Number of flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-length", "title": "Length", "rows": [{"code": "M", "meaning": "Medium length"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-apmx", "title": "Cutting length", "rows": [{"code": "##", "meaning": "Cutting length in mm"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}, {"code": "SL", "meaning": "Safe-Lock shank (by Haimer), helical grooves that prevent pull-out"}, {"code": "W", "meaning": "Weldon shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-cf", "title": "CHATTER-FREE", "rows": [{"code": "CF", "meaning": "CHATTER-FREE: different helix and variable pitch for chatter damping"}]}, {"key": "t-corner", "title": "Corner", "rows": [{"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (R02 = 0.2 mm)"}, {"code": "RP#.#", "meaning": "Programmed radius (Rg) for CAM"}]}, {"key": "t-line", "title": "Line (before the overall length)", "rows": [{"code": "T", "meaning": "For titanium"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "C", "meaning": "With coolant holes / channels"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
